7 | // Converts LLM markdown to React nodes — no external lib, no dangerouslySetInnerHTML.
8 | // Handles: **bold**, *italic*, `code`, # headings (1-3), - / 1. lists.
9 | function parseMarkdown(text: string): React.ReactNode[] {
10 |   const lines = text.split('\n');
11 |   const out: React.ReactNode[] = [];
12 |   let listBuf: React.ReactNode[] = [];
13 |   let k = 0;
14 | 
15 |   const flush = () => {
16 |     if (listBuf.length) {
17 |       out.push(<ul key={k++} style={{ paddingLeft: 18, margin: '4px 0 8px' }}>{listBuf}</ul>);
18 |       listBuf = [];
19 |     }
20 |   };
21 | 
22 |   const inline = (raw: string): React.ReactNode[] =>
23 |     raw.split(/(\*\*[\s\S]*?\*\*|\*[\s\S]*?\*|`[^`]+`)/g).map((seg, i) => {
24 |       if (seg.startsWith('**') && seg.endsWith('**') && seg.length > 4)
25 |         return <strong key={i}>{seg.slice(2, -2)}</strong>;
26 |       if (seg.startsWith('*') && seg.endsWith('*') && seg.length > 2)
27 |         return <em key={i}>{seg.slice(1, -1)}</em>;
28 |       if (seg.startsWith('`') && seg.endsWith('`') && seg.length > 2)
29 |         return <code key={i} style={{ background: '#f3f4f6', padding: '1px 5px', borderRadius: 3, fontSize: '0.88em', fontFamily: 'monospace' }}>{seg.slice(1, -1)}</code>;
30 |       return seg;
31 |     });
32 | 
33 |   for (const line of lines) {
34 |     const h3 = line.match(/^###\s+(.*)/); if (h3) { flush(); out.push(<p key={k++} style={{ fontWeight: 600, margin: '8px 0 2px' }}>{inline(h3[1])}</p>); continue; }
35 |     const h2 = line.match(/^##\s+(.*)/);  if (h2) { flush(); out.push(<p key={k++} style={{ fontWeight: 600, fontSize: '1.04em', margin: '10px 0 2px' }}>{inline(h2[1])}</p>); continue; }
36 |     const h1 = line.match(/^#\s+(.*)/);   if (h1) { flush(); out.push(<p key={k++} style={{ fontWeight: 700, fontSize: '1.1em',  margin: '12px 0 4px' }}>{inline(h1[1])}</p>); continue; }
37 |     const bullet   = line.match(/^[-*]\s+(.*)/);
38 |     const numbered = line.match(/^\d+\.\s+(.*)/);
39 |     if (bullet || numbered) { listBuf.push(<li key={k++} style={{ marginBottom: 2 }}>{inline((bullet ?? numbered)![1])}</li>); continue; }
40 |     flush();
41 |     if (line.trim() === '') { out.push(<span key={k++} style={{ display: 'block', height: 6 }} />); continue; }
42 |     out.push(<span key={k++} style={{ display: 'block' }}>{inline(line)}</span>);
43 |   }
44 |   flush();
45 |   return out;
46 | }
