  useEffect(() => {
    api.assistant.chatHistory(wsId).then((hist: ChatMessage[]) => {
      setMessages(
        hist.map(m => ({
          id: String(m.id),
          role: m.role,
          content: m.content,
          sources: [],
        }))
      );
      setHistoryLoaded(true);
    });
  }, [wsId]);

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

