88 |       target: e.target,
89 |       label: e.label,
90 |       type: 'smoothstep',
91 |       style: { stroke: '#94a3b8', strokeWidth, opacity: 0.4 + strength * 0.5 },
92 |       labelStyle: { fontSize: 10, fill: '#6b7280' },
93 |       labelBgStyle: { fill: '#fff', fillOpacity: 0.85 },
94 |       labelBgPadding: [3, 5] as [number, number],
