34 | function renderMarkdown(md: string): string {
35 |   return md
36 |     .replace(/^### (.+)$/gm, '<h3>$1</h3>')
37 |     .replace(/^## (.+)$/gm, '<h2>$1</h2>')
38 |     .replace(/^# (.+)$/gm, '<h1>$1</h1>')
39 |     .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
40 |     .replace(/\*(.+?)\*/g, '<em>$1</em>')
41 |     .replace(/^- (.+)$/gm, '<li>$1</li>')
42 |     .replace(/(<li>.*<\/li>\n?)+/g, s => `<ul>${s}</ul>`)
43 |     .replace(/\n\n/g, '</p><p>')
44 |     .replace(/^(?!<[hul])/gm, '')
45 |     .split('\n')
46 |     .map(line => line.startsWith('<') ? line : line ? `<p>${line}</p>` : '')
47 |     .join('\n');
48 | }
