        </div>
        <button onClick={onClose} className="text-muted-foreground hover:text-foreground p-0.5">
          <X className="w-4 h-4" />
        </button>
      </div>
      <div className="px-5 py-4 border-b">
        <div className="flex items-center gap-2 text-sm font-medium text-foreground flex-wrap">
