10 | async function req<T>(url: string, options: RequestInit = {}): Promise<T> {
11 |   const resp = await fetch(`${BASE}${url}`, {
12 |     headers: { 'Content-Type': 'application/json', ...options.headers },
13 |     ...options,
14 |   });
15 |   if (!resp.ok) {
16 |     const detail = await resp.json().catch(() => ({ detail: resp.statusText }));
17 |     throw new Error(detail.detail || `HTTP ${resp.status}`);
18 |   }
19 |   return resp.json();
20 | }
