106 | function mapToReactFlowNodes(nodes: GraphNode[], importanceMap: Map<string, number>): Node[] {
107 |   return nodes.map(n => ({
108 |     id: n.id,
109 |     position: n.position,
110 |     data: { ...n.data, importance: importanceMap.get(n.id) ?? 0, focusMode: undefined },
111 |     type: 'conceptNode',
112 |   }));
113 | }
114 | 
115 | function mapToReactFlowEdges(edges: GraphEdge[]): Edge[] {
116 |   return edges.map(e => {
117 |     const strength: number = (e.data as Record<string, unknown>)?.strength as number ?? 0.7;
118 |     const strokeWidth = Math.max(1, Math.round(strength * 3.5));
119 |     return {
120 |       id: e.id,
121 |       source: e.source,
122 |       target: e.target,
123 |       label: e.label,
124 |       type: 'smoothstep',
125 |       style: { stroke: '#94a3b8', strokeWidth, opacity: 0.4 + strength * 0.5 },
126 |       labelStyle: { fontSize: 10, fill: '#6b7280' },
127 |       labelBgStyle: { fill: '#fff', fillOpacity: 0.85 },
128 |       labelBgPadding: [3, 5] as [number, number],
129 |       data: e.data,
130 |     };
131 |   });
132 | }
133 | 
134 | function buildImportanceMap(nodes: GraphNode[], edges: GraphEdge[]): Map<string, number> {
135 |   const degree = new Map<string, number>();
136 |   nodes.forEach(n => degree.set(n.id, 0));
137 |   edges.forEach(e => {
138 |     degree.set(e.source, (degree.get(e.source) ?? 0) + 1);
139 |     degree.set(e.target, (degree.get(e.target) ?? 0) + 1);
140 |   });
141 |   const max = Math.max(...Array.from(degree.values()), 1);
142 |   const result = new Map<string, number>();
143 |   degree.forEach((v, k) => result.set(k, v / max));
144 |   return result;
145 | }
