export default function AssistantChat() {
  const { workspaceId } = useParams<{ workspaceId: string }>();
  const wsId = Number(workspaceId);
  const location = useLocation();
  const [messages, setMessages] = useState<Message[]>([]);
  const [input, setInput] = useState((location.state as { prefill?: string } | null)?.prefill ?? '');
  const [loading, setLoading] = useState(false);
  const [historyLoaded, setHistoryLoaded] = useState(false);
  const bottomRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    api.assistant.chatHistory(wsId).then((hist: ChatMessage[]) => {
      setMessages(
        hist.map(m => ({
          id: String(m.id),
          role: m.role,
          content: m.content,
          sources: [],
        }))
      );
      setHistoryLoaded(true);
    });
  }, [wsId]);

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const send = async (question?: string) => {
    const q = (question ?? input).trim();
    if (!q || loading) return;
    setInput('');
    const userMsg: Message = { id: `u-${Date.now()}`, role: 'user', content: q };
    setMessages(prev => [...prev, userMsg]);
    setLoading(true);
    try {
      const resp = await api.assistant.ask(wsId, q);
      setMessages(prev => [...prev, {
        id: `a-${Date.now()}`,
        role: 'assistant',
        content: resp.answer,
        sources: resp.sources,
      }]);
    } catch (e: unknown) {
      setMessages(prev => [...prev, {
        id: `err-${Date.now()}`,
        role: 'assistant',
        content: `Error: ${e instanceof Error ? e.message : 'Unknown error'}`,
        sources: [],
        isError: true,
      }]);
    } finally {
      setLoading(false);
      inputRef.current?.focus();
    }
  };

  const empty = messages.length === 0 && historyLoaded;

  return (
    <div className="flex flex-col h-[calc(100vh-140px)] max-w-3xl mx-auto px-8">

