// ── colour palette ────────────────────────────────────────────────────

const TYPE_COLOURS: Record<string, { bg: string; border: string; dot: string; text: string }> = {
  Standard:      { bg: '#eff6ff', border: '#3b82f6', dot: '#3b82f6', text: '#1d4ed8' },
  Technology:    { bg: '#f5f3ff', border: '#8b5cf6', dot: '#8b5cf6', text: '#6d28d9' },
