        Search concepts
      </button>
    </div>
  );
}

function SearchOverlay({
  nodes, onSelect, onClose,
}: {
  nodes: Node[];
  onSelect: (nodeId: string) => void;
  onClose: () => void;
}) {
  const [q, setQ] = useState('');
  const inputRef = useRef<HTMLInputElement>(null);
