109 | function mapToReactFlowEdges(edges: GraphEdge[]): Edge[] {
110 |   return edges.map(e => {
111 |     const strength: number = (e.data as Record<string, unknown>)?.strength as number ?? 0.7;
112 |     const strokeWidth = Math.max(1, Math.round(strength * 3.5));
113 |     return {
114 |       id: e.id,
115 |       source: e.source,
116 |       target: e.target,
117 |       label: e.label,
118 |       type: 'smoothstep',
119 |       style: { stroke: '#94a3b8', strokeWidth, opacity: 0.4 + strength * 0.5 },
120 |       labelStyle: { fontSize: 10, fill: '#6b7280' },
121 |       labelBgStyle: { fill: '#fff', fillOpacity: 0.85 },
122 |       labelBgPadding: [3, 5] as [number, number],
123 |       data: e.data,
124 |     };
125 |   });
126 | }
