128 | function buildImportanceMap(nodes: GraphNode[], edges: GraphEdge[]): Map<string, number> {
129 |   const degree = new Map<string, number>();
130 |   nodes.forEach(n => degree.set(n.id, 0));
131 |   edges.forEach(e => {
132 |     degree.set(e.source, (degree.get(e.source) ?? 0) + 1);
133 |     degree.set(e.target, (degree.get(e.target) ?? 0) + 1);
134 |   });
135 |   const max = Math.max(...Array.from(degree.values()), 1);
136 |   const result = new Map<string, number>();
137 |   degree.forEach((v, k) => result.set(k, v / max));
138 |   return result;
139 | }
