                >
                  <span style={{ width: 7, height: 7, borderRadius: '50%', background: nCol.dot, flexShrink: 0, marginTop: 4 }} />
                  <div className="min-w-0 flex-1">
                    <p className="text-xs font-medium text-foreground leading-tight">{n.name}</p>
