        <p className="text-[11px] font-semibold text-muted-foreground uppercase tracking-wider mb-2">Ask the assistant</p>
        <div className="grid grid-cols-2 gap-1.5">
          {suggestedQuestions.slice(0, 2).map((q, i) => (
