function fileTypeLabel(ft: string): string {
  const m: Record<string, string> = {
    pdf: 'PDF', docx: 'Word', pptx: 'PowerPoint', xlsx: 'Excel', xls: 'Excel', csv: 'CSV',
  };
  return m[ft?.toLowerCase()] ?? ft?.toUpperCase() ?? 'Doc';
}

const FILE_TYPE_BADGE_STYLES: Record<string, { bg: string; border: string; color: string }> = {
  pdf:  { bg: '#fff1f2', border: '#f87171', color: '#b91c1c' },
  docx: { bg: '#eff6ff', border: '#60a5fa', color: '#1d4ed8' },
  pptx: { bg: '#fff7ed', border: '#fb923c', color: '#c2410c' },
  xlsx: { bg: '#f0fdf4', border: '#4ade80', color: '#15803d' },
  xls:  { bg: '#f0fdf4', border: '#4ade80', color: '#15803d' },
  csv:  { bg: '#f8fafc', border: '#94a3b8', color: '#334155' },
};

function getFileTypeBadgeStyle(ft: string) {
  return FILE_TYPE_BADGE_STYLES[ft?.toLowerCase()] ?? { bg: '#f9fafb', border: '#d1d5db', color: '#6b7280' };
}

