            <div className="mt-2 flex items-center gap-2">
              <span
                className="text-[10px] font-bold px-1.5 py-0.5 rounded flex-shrink-0"
                style={(() => { const s = getFileTypeBadgeStyle(selected.source_document.file_type); return { background: s.bg, border: `1px solid ${s.border}`, color: s.color }; })()}
