      {hasGraph && (
        <div className="mt-1 flex items-center gap-1.5 text-[11px] text-green-600 font-medium">
          <span className="w-1.5 h-1.5 rounded-full bg-green-500" />
          Knowledge graph ready
        </div>
      )}
    </div>
  );
}

