import { useCallback, useEffect, useRef, useState } from 'react';
import { useParams } from 'react-router-dom';
import { api } from '@/api/client';
import type { Document } from '@/types/api';
import {
  Upload, CheckCircle, XCircle, Loader2, Clock,
  Trash2, FileText, Info, Database,
} from 'lucide-react';

const FILE_TYPE_META: Record<string, { label: string; badge: string; bg: string; border: string; text: string; use: string }> = {
  pdf:  { label: 'PDF',        badge: 'PDF',   bg: '#fff1f2', border: '#f87171', text: '#b91c1c', use: 'Research · POVs · Proposals' },
  docx: { label: 'Word',       badge: 'DOCX',  bg: '#eff6ff', border: '#60a5fa', text: '#1d4ed8', use: 'BRDs · Requirements · Specs' },
  pptx: { label: 'PowerPoint', badge: 'PPTX',  bg: '#fff7ed', border: '#fb923c', text: '#c2410c', use: 'Decks · Architecture · POVs' },
  xlsx: { label: 'Excel',      badge: 'XLSX',  bg: '#f0fdf4', border: '#4ade80', text: '#15803d', use: 'Requirements matrices · Data' },
  xls:  { label: 'Excel (97)', badge: 'XLS',   bg: '#f0fdf4', border: '#4ade80', text: '#15803d', use: 'Legacy spreadsheets' },
  csv:  { label: 'CSV',        badge: 'CSV',   bg: '#f8fafc', border: '#94a3b8', text: '#334155', use: 'Structured data exports' },
};

function getFileMeta(fileType: string) {
  return FILE_TYPE_META[fileType.toLowerCase()] ?? {
    label: fileType.toUpperCase(), badge: fileType.toUpperCase(),
    bg: '#f9fafb', border: '#d1d5db', text: '#6b7280', use: '',
  };
}

function FileTypeBadge({ fileType }: { fileType: string }) {
  const m = getFileMeta(fileType);
  return (
    <span
      className="inline-flex items-center text-[10px] font-semibold px-1.5 py-0.5 rounded flex-shrink-0"
      style={{ background: m.bg, border: `1px solid ${m.border}`, color: m.text }}
    >
      {m.badge}
    </span>
  );
}

const PIPELINE_STEPS = [
  { key: 'parsed',    label: 'Parsed',              desc: 'Text & structure extracted' },
  { key: 'concepts',  label: 'Concepts extracted',  desc: 'Named entities identified' },
  { key: 'relations', label: 'Relationships mapped', desc: 'Concept links traced' },
  { key: 'graph',     label: 'Graph updated',        desc: 'Knowledge graph incremented' },
  { key: 'patterns',  label: 'Pattern analysis',     desc: 'Recurring patterns evaluated' },
];

function PipelineSteps({ status }: { status: Document['upload_status'] }) {
  const completedCount =
    status === 'complete'    ? 5 :
    status === 'processing'  ? 2 :   // mid-flight: parsed + concepts done, rest in progress
    status === 'pending'     ? 0 :
    0;                               // failed shows 0 completed

  return (
    <div className="mt-2 flex flex-wrap gap-1">
      {PIPELINE_STEPS.map((step, i) => {
        const done    = i < completedCount;
        const active  = status === 'processing' && i === completedCount;
        const waiting = !done && !active;
        return (
          <span
            key={step.key}
            className="inline-flex items-center gap-1 text-[10px] px-1.5 py-0.5 rounded"
            style={{
              background: done ? '#f0fdf4' : active ? '#eff6ff' : '#f9fafb',
              border: `1px solid ${done ? '#bbf7d0' : active ? '#bfdbfe' : '#e5e7eb'}`,
              color: done ? '#15803d' : active ? '#1d4ed8' : '#9ca3af',
            }}
            title={step.desc}
          >
            {done  && <CheckCircle className="w-2.5 h-2.5" />}
            {active && <Loader2 className="w-2.5 h-2.5 animate-spin" />}
            {waiting && <Clock className="w-2.5 h-2.5" />}
            {step.label}
          </span>
        );
      })}
    </div>
  );
}

const STATUS_CONFIG = {
  pending:    { label: 'Queued',     icon: Clock,        color: 'text-muted-foreground' },
  processing: { label: 'Processing', icon: Loader2,      color: 'text-primary' },
  complete:   { label: 'Ready',      icon: CheckCircle,  color: 'text-green-600' },
  failed:     { label: 'Failed',     icon: XCircle,      color: 'text-destructive' },
} as const;

function StatusBadge({ status }: { status: Document['upload_status'] }) {
  const cfg = STATUS_CONFIG[status] ?? STATUS_CONFIG.pending;
  const Icon = cfg.icon;
  return (
    <span className={`flex items-center gap-1.5 text-xs font-medium ${cfg.color}`}>
      <Icon className={`w-3.5 h-3.5 ${status === 'processing' ? 'animate-spin' : ''}`} />
      {cfg.label}
    </span>
  );
}

