        <p className="text-sm text-muted-foreground mt-1.5 leading-relaxed">
          Upload consulting assets in any supported format. Every document is automatically run through the
          knowledge compilation pipeline — no manual tagging required. All results trace back to verbatim source evidence.
        </p>
      </div>

      {/* Supported formats grid */}
      <div className="mb-7 border bg-white p-4">
        <div className="flex items-center gap-1.5 mb-3">
          <Info className="w-3.5 h-3.5 text-primary" />
          <p className="text-xs font-semibold text-foreground">Supported document types</p>
        </div>
        <div className="grid grid-cols-3 gap-2">
          {Object.entries(FILE_TYPE_META).map(([type, m]) => (
            <div
              key={type}
