              style={{ background: m.bg, border: `1px solid ${m.border}` }}
            >
              <span
                className="text-[10px] font-bold px-1.5 py-0.5 rounded mt-0.5 flex-shrink-0"
                style={{ background: m.border, color: '#fff' }}
              >
                {m.badge}
              </span>
              <div>
                <p className="text-xs font-semibold" style={{ color: m.text }}>{m.label}</p>
                <p className="text-[10px] text-muted-foreground leading-snug mt-0.5">{m.use}</p>
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* Pipeline steps overview */}
      <div className="mb-7 border bg-white p-4">
        <div className="flex items-center gap-1.5 mb-3">
          <Info className="w-3.5 h-3.5 text-primary" />
          <p className="text-xs font-semibold text-foreground">What happens after upload</p>
        </div>
        <div className="flex items-center gap-0 flex-wrap">
          {PIPELINE_STEPS.map((step, i) => (
            <div key={step.key} className="flex items-center">
              <div className="flex items-center gap-1.5 px-2 py-1.5">
