7 | function parseMarkdown(text: string): React.ReactNode[] {
8 |   const lines = text.split('\n');
9 |   const out: React.ReactNode[] = [];
10 |   let listBuf: React.ReactNode[] = [];
11 |   let k = 0;
12 | 
13 |   const flush = () => {
14 |     if (listBuf.length) {
15 |       out.push(<ul key={k++} style={{ paddingLeft: 18, margin: '4px 0 8px' }}>{listBuf}</ul>);
16 |       listBuf = [];
17 |     }
18 |   };
19 | 
20 |   const inline = (raw: string): React.ReactNode[] =>
21 |     raw.split(/(\*\*[\s\S]*?\*\*|\*[\s\S]*?\*|`[^`]+`)/g).map((seg, i) => {
22 |       if (seg.startsWith('**') && seg.endsWith('**') && seg.length > 4)
23 |         return <strong key={i}>{seg.slice(2, -2)}</strong>;
24 |       if (seg.startsWith('*') && seg.endsWith('*') && seg.length > 2)
25 |         return <em key={i}>{seg.slice(1, -1)}</em>;
26 |       if (seg.startsWith('`') && seg.endsWith('`') && seg.length > 2)
27 |         return <code key={i} style={{ background: '#f3f4f6', padding: '1px 5px', borderRadius: 3, fontSize: '0.88em', fontFamily: 'monospace' }}>{seg.slice(1, -1)}</code>;
28 |       return seg;
29 |     });
30 | 
31 |   for (const line of lines) {
32 |     const h3 = line.match(/^###\s+(.*)/); if (h3) { flush(); out.push(<p key={k++} style={{ fontWeight: 600, margin: '8px 0 2px' }}>{inline(h3[1])}</p>); continue; }
33 |     const h2 = line.match(/^##\s+(.*)/);  if (h2) { flush(); out.push(<p key={k++} style={{ fontWeight: 600, fontSize: '1.04em', margin: '10px 0 2px' }}>{inline(h2[1])}</p>); continue; }
34 |     const h1 = line.match(/^#\s+(.*)/);   if (h1) { flush(); out.push(<p key={k++} style={{ fontWeight: 700, fontSize: '1.1em',  margin: '12px 0 4px' }}>{inline(h1[1])}</p>); continue; }
35 |     const bullet   = line.match(/^[-*]\s+(.*)/);
36 |     const numbered = line.match(/^\d+\.\s+(.*)/);
37 |     if (bullet || numbered) { listBuf.push(<li key={k++} style={{ marginBottom: 2 }}>{inline((bullet ?? numbered)![1])}</li>); continue; }
38 |     flush();
39 |     if (line.trim() === '') { out.push(<span key={k++} style={{ display: 'block', height: 6 }} />); continue; }
40 |     out.push(<span key={k++} style={{ display: 'block' }}>{inline(line)}</span>);
41 |   }
42 |   flush();
43 |   return out;
44 | }
