            : '0 1px 3px rgba(0,0,0,0.07)',
          opacity: isFocused ? 0.25 : 1,
          transition: 'opacity 0.2s, box-shadow 0.15s',
          transform: `scale(${scale})`,
          transformOrigin: 'center center',
