  const m: Record<string, string> = {
    pdf: 'PDF', docx: 'Word', pptx: 'PowerPoint', xlsx: 'Excel', xls: 'Excel', csv: 'CSV',
  };
  return m[ft?.toLowerCase()] ?? ft?.toUpperCase() ?? 'Doc';
}

