    setFocusNodeId(null);
    setPathHighlight(new Set());
  }, []);

  const toggleTypeFilter = useCallback((type: string) => {
    setActiveTypeFilters(prev => {
      const next = new Set(prev);
      if (next.has(type)) { next.delete(type); } else { next.add(type); }
