          focusNeighbours.add(e.source);
          focusNeighbours.add(e.target);
        }
      });
      visibleNodes = visibleNodes.map(n => ({
        ...n,
        data: { ...n.data, focusMode: !focusNeighbours.has(n.id) },
      }));
