          padding: `${7 * scale}px ${11 * scale}px`,
          minWidth: 90 * scale,
          maxWidth: 170 * scale,
          boxShadow: selected
            ? `0 0 0 3px ${col.border}33, 0 2px 8px rgba(0,0,0,0.12)`
            : '0 1px 3px rgba(0,0,0,0.07)',
          opacity: isFocused ? 0.25 : 1,
          transition: 'opacity 0.2s, box-shadow 0.15s',
