        </button>
      </div>

      <div className="px-5 pt-5 pb-4 border-b">
        <div className="flex items-start gap-3 mb-2">
          <span style={{ width: 10, height: 10, borderRadius: 3, background: col.bg, border: `2px solid ${col.border}`, flexShrink: 0, marginTop: 4 }} />
