function ConceptNode({ data, selected }: NodeProps) {
  const col = getTypeColour(data.type);
  const scale = Math.max(0.85, Math.min(1.35, 1 + (data.importance ?? 0) * 0.35));
  const isFocused = data.focusMode === true;

