                Document type
              </label>
              <div className="grid grid-cols-3 gap-3">
                {TYPES.map(t => (
                  <button
                    key={t.id}
                    type="button"
                    onClick={() => setDelivType(t.id)}
                    className={`text-left p-3.5 border transition-colors ${
                      delivType === t.id
