type Tab = 'generate' | 'list';
type DeliverableType = 'POV' | 'executive_summary' | 'roadmap';

const TYPES: { id: DeliverableType; label: string; headline: string; desc: string; sections: string[] }[] = [
  {
    id: 'POV',
